-- Replace corrupted character-level vocabulary and split Book 3 into individual lesson rules.
begin;

delete from public.rule_sections
where rule_id in (
  select id from public.rules where course_name = 'Мединский курс (Том 3)'
);
delete from public.rules where course_name = 'Мединский курс (Том 3)';
delete from public.words where course_name = 'Мединский курс (Том 3)';

with rule_data (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('1', 1, 'الإِعْرَابُ وَالْبِنَاءُ (И‘раб и бина)', 'Изменяемые и неизменяемые имена.', 'И‘раб — изменение конечной огласовки имени под влиянием синтаксической позиции; бина — постоянство формы. В уроке различаются марфу‘, мансуб и маджрур у изменяемого имени.', '<li><span dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُ</span> — преподаватель пришёл.</li><li><span dir="rtl" lang="ar">سَأَلْتُ الْمُدَرِّسَ</span> — я спросил преподавателя.</li><li><span dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُدَرِّسِ</span> — я поприветствовал преподавателя.</li>', '<span dir="rtl" lang="ar">الْمُدَرِّسُ: فَاعِلٌ مَرْفُوعٌ وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ.</span>'),
  ('1', 2, 'عَلَامَاتُ الإِعْرَابِ (Падежные показатели)', 'Основные и вторичные показатели падежа.', 'Основные показатели: дамма для раф‘а, фатха для насба и касра для джарра. Вторичные показатели появляются, например, в двойственном числе и правильном мужском множественном числе.', '<li><span dir="rtl" lang="ar">هَذَا طَالِبٌ</span> — это студент.</li><li><span dir="rtl" lang="ar">رَأَيْتُ طَالِبَيْنِ</span> — я увидел двух студентов.</li><li><span dir="rtl" lang="ar">سَلَّمْتُ عَلَى الْمُسْلِمِينَ</span> — я поприветствовал мусульман.</li>', '<span dir="rtl" lang="ar">طَالِبَيْنِ: مَفْعُولٌ بِهِ مَنْصُوبٌ بِالْيَاءِ لِأَنَّهُ مُثَنًّى.</span>'),
  ('1', 3, 'الإِعْرَابُ التَّقْدِيرِيُّ وَالْحَالُ (Скрытый и‘раб и обстоятельство состояния)', 'Окончание может быть скрытым; халь передаёт временное состояние.', 'Скрытый и‘раб не произносится по фонетической причине, но устанавливается по синтаксической позиции. Халь обычно является неопределённым словом в винительном падеже и описывает состояние участника действия.', '<li><span dir="rtl" lang="ar">جَاءَ الْفَتَى</span> — юноша пришёл.</li><li><span dir="rtl" lang="ar">رَأَيْتُ الْفَتَى</span> — я увидел юношу.</li><li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ مُبْتَسِمًا</span> — студент пришёл улыбаясь.</li>', '<span dir="rtl" lang="ar">مُبْتَسِمًا: حَالٌ مَنْصُوبٌ بِالْفَتْحَةِ.</span>'),
  ('2', 4, 'الْفِعْلُ الثُّلَاثِيُّ الْمُجَرَّدُ (Простой трёхбуквенный глагол)', 'Основа сарфа: три корневые буквы без добавочных.', 'Трёхбуквенный простой глагол состоит из корня и относится к одному из известных типов настоящего времени. Значение и модель необходимо запоминать вместе с формой прошедшего и настоящего времени.', '<li><span dir="rtl" lang="ar">كَتَبَ يَكْتُبُ</span> — писать.</li><li><span dir="rtl" lang="ar">جَلَسَ يَجْلِسُ</span> — сидеть.</li><li><span dir="rtl" lang="ar">فَتَحَ يَفْتَحُ</span> — открывать.</li>', '<span dir="rtl" lang="ar">كَتَبَ: فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ.</span>'),
  ('2', 5, 'الْمَبْنِيُّ لِلْمَجْهُولِ (Страдательный залог)', 'Действующий субъект не называется; объект становится заместителем подлежащего.', 'В прошедшем времени простого глагола пассив обычно образуется по модели فُعِلَ, а в настоящем — يُفْعَلُ. Именная группа, которая была объектом, становится نَائِبَ فَاعِلٍ и получает раф‘.', '<li><span dir="rtl" lang="ar">كُتِبَ الدَّرْسُ</span> — урок был написан.</li><li><span dir="rtl" lang="ar">يُفْتَحُ الْبَابُ</span> — дверь открывается.</li><li><span dir="rtl" lang="ar">حُفِظَ الْقُرْآنُ</span> — Коран был выучен.</li>', '<span dir="rtl" lang="ar">الدَّرْسُ: نَائِبُ فَاعِلٍ مَرْفُوعٌ بِالضَّمَّةِ.</span>'),
  ('3', 6, 'هَاءُ الضَّمِيرِ (Местоименное ха)', 'Присоединённое местоимение обозначает владельца, объект или адресата.', 'Ха местоимения присоединяется к имени, глаголу или предлогу. Его синтаксическая роль устанавливается по слову, к которому оно присоединено: мудоф иляйхи, объект или местоимение после предлога.', '<li><span dir="rtl" lang="ar">كِتَابُهُ جَدِيدٌ</span> — его книга новая.</li><li><span dir="rtl" lang="ar">رَأَيْتُهُ</span> — я увидел его.</li><li><span dir="rtl" lang="ar">سَلَّمْتُ عَلَيْهِ</span> — я поприветствовал его.</li>', '<span dir="rtl" lang="ar">هُ: ضَمِيرٌ مُتَّصِلٌ فِي مَحَلِّ جَرٍّ مُضَافٍ إِلَيْهِ.</span>'),
  ('3', 7, 'النِّسْبَةُ وَالْأَلِفُ الْفَارِقَةُ (Нисба и различительный алиф)', 'Нисба образует относительное прилагательное; алиф после واو الجماعة не произносится.', 'Относительное прилагательное обычно строится с окончанием يّ. Различительный алиф пишется после واو الجماعة в глагольной форме, но не является самостоятельным звуком.', '<li><span dir="rtl" lang="ar">طَالِبٌ مِصْرِيٌّ</span> — египетский студент.</li><li><span dir="rtl" lang="ar">هُمْ كَتَبُوا الدَّرْسَ</span> — они написали урок.</li><li><span dir="rtl" lang="ar">هَذَا كِتَابٌ عَرَبِيٌّ</span> — это арабская книга.</li>', '<span dir="rtl" lang="ar">مِصْرِيٌّ: نَعْتٌ مَرْفُوعٌ وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ.</span>'),
  ('4', 8, 'اسْمُ الْفَاعِلِ مِنَ الصَّحِيحِ (Действительное причастие)', 'Форма, обозначающая носителя действия.', 'От правильного трёхбуквенного глагола действительное причастие обычно образуется по модели فَاعِلٌ. Оно согласуется с определяемым словом по определённости, роду, числу и падежу.', '<li><span dir="rtl" lang="ar">هَذَا طَالِبٌ كَاتِبٌ</span> — это пишущий студент.</li><li><span dir="rtl" lang="ar">جَاءَ رَجُلٌ حَافِظٌ</span> — пришёл помнящий мужчина.</li><li><span dir="rtl" lang="ar">رَأَيْتُ طَالِبًا جَالِسًا</span> — я увидел сидящего студента.</li>', '<span dir="rtl" lang="ar">كَاتِبٌ: نَعْتٌ مَرْفُوعٌ تَابِعٌ لِطَالِبٍ.</span>'),
  ('4', 9, 'اسْمُ الْمَفْعُولِ وَمَا الْحِجَازِيَّةُ (Страдательное причастие и ма-хиджазийя)', 'Страдательное причастие называет объект действия; ما может действовать как لَيْسَ.', 'От правильного трёхбуквенного глагола страдательное причастие обычно имеет модель مَفْعُولٌ. Частица مَا الْحِجَازِيَّةُ отрицает именное предложение: её имя получает раф‘, а хабар — насб.', '<li><span dir="rtl" lang="ar">هَذَا دَرْسٌ مَكْتُوبٌ</span> — это написанный урок.</li><li><span dir="rtl" lang="ar">الْبَابُ مَفْتُوحٌ</span> — дверь открыта.</li><li><span dir="rtl" lang="ar">مَا الطَّالِبُ غَائِبًا</span> — студент не отсутствует.</li>', '<span dir="rtl" lang="ar">غَائِبًا: خَبَرُ مَا مَنْصُوبٌ بِالْفَتْحَةِ.</span>'),
  ('5', 10, 'اسْمَا الْفَاعِلِ وَالْمَفْعُولِ مِنَ الْمُعْتَلِّ (Причастия слабого глагола)', 'Слабая буква влияет на строение производной формы.', 'При образовании причастий от слабых глаголов учитываются тип слабости и фонетические изменения. Форму следует проверять как самостоятельную словарную единицу: قَائِلٌ, دَاعٍ, مَقُولٌ.', '<li><span dir="rtl" lang="ar">هُوَ دَاعٍ إِلَى الْخَيْرِ</span> — он призывающий к добру.</li><li><span dir="rtl" lang="ar">هَذَا قَوْلٌ مَقُولٌ</span> — это сказанное высказывание.</li><li><span dir="rtl" lang="ar">رَأَيْتُ رَجُلًا قَائِلًا الْحَقَّ</span> — я увидел человека, говорящего истину.</li>', '<span dir="rtl" lang="ar">دَاعٍ: خَبَرٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ عَلَى الْيَاءِ الْمَحْذُوفَةِ.</span>'),
  ('5', 11, 'الْفِعْلُ الْأَجْوَفُ فِي الْمَبْنِيِّ لِلْمَجْهُولِ (Пустотелый глагол в пассиве)', 'Средняя слабая буква вызывает изменение гласной в пассивной форме.', 'У пустотелого глагола слабая буква находится между первой и последней корневыми. В пассиве его огласовка меняется по правилу формы: قَالَ — قِيلَ, بَاعَ — بِيعَ.', '<li><span dir="rtl" lang="ar">قِيلَ لَهُ</span> — ему было сказано.</li><li><span dir="rtl" lang="ar">بِيعَ الْكِتَابُ</span> — книга была продана.</li><li><span dir="rtl" lang="ar">يُقَالُ الْحَقُّ</span> — говорится истина.</li>', '<span dir="rtl" lang="ar">الْكِتَابُ: نَائِبُ فَاعِلٍ مَرْفُوعٌ بِالضَّمَّةِ.</span>'),
  ('6', 12, 'اسْمَا الزَّمَانِ وَالْمَكَانِ (Имена времени и места)', 'Производные имена обозначают время или место действия.', 'Имена времени и места называют, где или когда совершается действие. Для трёхбуквенных глаголов распространены модели مَفْعِلٌ и مَفْعَلٌ; конкретная форма определяется словарём и моделью глагола.', '<li><span dir="rtl" lang="ar">الْمَسْجِدُ مَكَانُ الصَّلَاةِ</span> — мечеть является местом молитвы.</li><li><span dir="rtl" lang="ar">هَذَا مَوْعِدُ الدَّرْسِ</span> — это время урока.</li><li><span dir="rtl" lang="ar">دَخَلْتُ مَكْتَبَ الْمُدَرِّسِ</span> — я вошёл в кабинет преподавателя.</li>', '<span dir="rtl" lang="ar">مَكْتَبَ: مَفْعُولٌ بِهِ مَنْصُوبٌ وَهُوَ مُضَافٌ.</span>'),
  ('7', 13, 'اسْمُ الْآلَةِ (Имя орудия)', 'Производное имя обозначает инструмент, которым совершается действие.', 'Имя орудия связывает предмет с действием и часто имеет модели مِفْعَلٌ, مِفْعَالٌ и مِفْعَلَةٌ. Оно склоняется как обычное имя и может входить в идафу.', '<li><span dir="rtl" lang="ar">هَذَا مِفْتَاحُ الْبَابِ</span> — это ключ от двери.</li><li><span dir="rtl" lang="ar">كَتَبْتُ بِالْمِفْتَاحِ</span> — я написал инструментом.</li><li><span dir="rtl" lang="ar">اسْتَعْمَلْتُ مِكْنَسَةً</span> — я использовал метлу.</li>', '<span dir="rtl" lang="ar">مِفْتَاحُ: مُبْتَدَأٌ مَرْفُوعٌ وَهُوَ مُضَافٌ.</span>'),
  ('7', 14, 'أَوْزَانُ اسْمِ الْآلَةِ (Модели имени орудия)', 'Модель помогает узнавать значение, но не заменяет словарь.', 'Классические модели имени орудия указывают на связь с действием, однако не каждая форма выводится механически. Значение и нормативную огласовку необходимо запоминать вместе со словом.', '<li><span dir="rtl" lang="ar">مِفْتَاحٌ</span> — ключ.</li><li><span dir="rtl" lang="ar">مِكْنَسَةٌ</span> — метла.</li><li><span dir="rtl" lang="ar">مِنْشَارٌ</span> — пила.</li>', '<span dir="rtl" lang="ar">مِنْشَارٌ: اسْمٌ مَرْفُوعٌ بِالضَّمَّةِ فِي مَوْضِعِهِ السِّيَاقِيِّ.</span>'),
  ('8', 15, 'الْمَعْرِفَةُ (Определённое имя)', 'Определённое имя указывает на известный адресату объект.', 'К определённым именам относятся собственные имена, местоимения, указательные и относительные слова, имена с ال и члены идафы, определённые через второй член. Определённость важна для согласования определения.', '<li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ</span> — пришёл студент.</li><li><span dir="rtl" lang="ar">هَذَا كِتَابُ الْمُدَرِّسِ</span> — это книга преподавателя.</li><li><span dir="rtl" lang="ar">مُحَمَّدٌ حَاضِرٌ</span> — Мухаммад присутствует.</li>', '<span dir="rtl" lang="ar">الطَّالِبُ: فَاعِلٌ مَعْرِفَةٌ بِأَلْ.</span>'),
  ('8', 16, 'النَّكِرَةُ (Неопределённое имя)', 'Неопределённое имя называет предмет без индивидуализации.', 'Неопределённое имя обычно принимает танвин, если нет другого препятствия. Оно может стать определённым через ال, идафу, указательное слово или иной контекст.', '<li><span dir="rtl" lang="ar">جَاءَ رَجُلٌ</span> — пришёл мужчина.</li><li><span dir="rtl" lang="ar">عِنْدِي كِتَابٌ</span> — у меня есть книга.</li><li><span dir="rtl" lang="ar">رَأَيْتُ طَالِبًا</span> — я увидел студента.</li>', '<span dir="rtl" lang="ar">رَجُلٌ: فَاعِلٌ مَرْفُوعٌ وَهُوَ نَكِرَةٌ.</span>'),
  ('9', 17, 'حَذْفُ نُونِ الْمُثَنَّى (Удаление нуна двойственного числа)', 'Нун двойственного числа удаляется перед идафой.', 'В двойственном числе нун является частью окончания. При присоединении первого члена идафы он удаляется: رَكْعَتَانِ превращается в رَكْعَتَا в сочетании رَكْعَتَا الْفَجْرِ.', '<li><span dir="rtl" lang="ar">رَكْعَتَانِ</span> — две рак‘аты.</li><li><span dir="rtl" lang="ar">رَكْعَتَا الْفَجْرِ</span> — две рак‘аты рассветной молитвы.</li><li><span dir="rtl" lang="ar">رَأَيْتُ طَالِبَيْ الْفَصْلِ</span> — я увидел двух учеников класса.</li>', '<span dir="rtl" lang="ar">رَكْعَتَا: مُبْتَدَأٌ مَرْفُوعٌ بِالْأَلِفِ وَهُوَ مُضَافٌ.</span>'),
  ('9', 18, 'حَذْفُ نُونِ جَمْعِ الْمُذَكَّرِ السَّالِمِ (Удаление нуна правильного мужского множественного)', 'Нун правильного мужского множественного удаляется перед идафой.', 'При идафе форма مُسْلِمُونَ становится مُسْلِمُو, а مُسْلِمِينَ — مُسْلِمِي. Падежный показатель сохраняется, удаляется только нун окончания.', '<li><span dir="rtl" lang="ar">الْمُسْلِمُونَ</span> — мусульмане.</li><li><span dir="rtl" lang="ar">مُسْلِمُو الْيَابَانِ</span> — мусульмане Японии.</li><li><span dir="rtl" lang="ar">سَلَّمْتُ عَلَى مُسْلِمِي الْمَدِينَةِ</span> — я поприветствовал мусульман города.</li>', '<span dir="rtl" lang="ar">مُسْلِمِي: اسْمٌ مَجْرُورٌ بِالْيَاءِ وَهُوَ مُضَافٌ.</span>'),
  ('10', 19, 'الْجُمْلَةُ الاسْمِيَّةُ وَالْجُمْلَةُ الْفِعْلِيَّةُ (Именное и глагольное предложение)', 'Тип предложения определяется его начальным элементом.', 'Именное предложение начинается с имени и строится вокруг мубтада и хабар. Глагольное предложение начинается с глагола и обычно включает глагол, подлежащее и при необходимости объект.', '<li><span dir="rtl" lang="ar">الْعِلْمُ نَافِعٌ</span> — знание полезно.</li><li><span dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</span> — студент написал урок.</li><li><span dir="rtl" lang="ar">الْوَلَدُ يَقْرَأُ الْكِتَابَ</span> — мальчик читает книгу.</li>', '<span dir="rtl" lang="ar">الْعِلْمُ: مُبْتَدَأٌ مَرْفُوعٌ، نَافِعٌ: خَبَرٌ مَرْفُوعٌ.</span>'),
  ('10', 20, 'الْمَصْدَرُ الْمُؤَوَّلُ (Интерпретируемый масдар)', 'Сочетание частицы и глагольного предложения может выполнять роль масдара.', 'Сочетание أَنْ с глаголом настоящего времени интерпретируется как масдар и занимает позицию имени в предложении. Его падеж устанавливается по синтаксической функции всего сочетания.', '<li><span dir="rtl" lang="ar">أُرِيدُ أَنْ أَدْرُسَ</span> — я хочу учиться.</li><li><span dir="rtl" lang="ar">يَسُرُّنِي أَنْ تَحْضُرَ</span> — меня радует, что ты придёшь.</li><li><span dir="rtl" lang="ar">جِئْتُ لِأَنْ أَتَعَلَّمَ</span> — я пришёл, чтобы учиться.</li>', '<span dir="rtl" lang="ar">أَنْ أَدْرُسَ: مَصْدَرٌ مُؤَوَّلٌ فِي مَحَلِّ نَصْبِ مَفْعُولٍ بِهِ.</span>'),
  ('11', 21, 'الْمُبْتَدَأُ (Подлежащее именного предложения)', 'Мубтада — исходный член именного предложения и обычно стоит в раф‘е.', 'Мубтада сообщает, о чём будет сказано далее. Обычно он определён, однако может быть неопределённым при наличии смыслового основания, например в обстоятельственной конструкции.', '<li><span dir="rtl" lang="ar">اللَّهُ غَفُورٌ</span> — Аллах Прощающий.</li><li><span dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ</span> — студент прилежен.</li><li><span dir="rtl" lang="ar">فِي الْفَصْلِ طَالِبٌ</span> — в классе есть студент.</li>', '<span dir="rtl" lang="ar">الطَّالِبُ: مُبْتَدَأٌ مَرْفُوعٌ بِالضَّمَّةِ.</span>'),
  ('11', 22, 'الْخَبَرُ (Сказуемое именного предложения)', 'Хабар завершает основное сообщение о мубтада.', 'Хабар может быть одним словом, предложением или شبه جملة. Он согласуется с логикой сообщения, а не обязательно внешне повторяет форму мубтада.', '<li><span dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ</span> — студент прилежен.</li><li><span dir="rtl" lang="ar">الْكِتَابُ عَلَى الطَّاوِلَةِ</span> — книга на столе.</li><li><span dir="rtl" lang="ar">الطَّالِبُ يَقْرَأُ</span> — студент читает.</li>', '<span dir="rtl" lang="ar">مُجْتَهِدٌ: خَبَرٌ مَرْفُوعٌ بِالضَّمَّةِ.</span>'),
  ('12', 23, 'الْمَفْعُولُ فِيهِ (Обстоятельство времени и места)', 'Зарф определяет время или место действия.', 'Маф‘уль фихи обычно является именем в винительном падеже и отвечает на вопросы «когда?» или «где?». Его смысл связан с действием, выраженным в предложении.', '<li><span dir="rtl" lang="ar">جَلَسْتُ أَمَامَ الْمُدَرِّسِ</span> — я сел перед преподавателем.</li><li><span dir="rtl" lang="ar">سَافَرْتُ لَيْلًا</span> — я путешествовал ночью.</li><li><span dir="rtl" lang="ar">دَرَسْتُ بَعْدَ الْعَصْرِ</span> — я учился после асра.</li>', '<span dir="rtl" lang="ar">أَمَامَ: ظَرْفُ مَكَانٍ مَنْصُوبٌ وَهُوَ مُضَافٌ.</span>'),
  ('12', 24, 'مِنْ قَبْلُ وَمِنْ بَعْدُ (Прежде и после)', 'Наречные формы могут быть построены или входить в идафу.', 'Слова قَبْلُ и بَعْدُ используются как обстоятельства времени. В построенной форме после مِنْ они получают дамму; при идафе их падежное окончание зависит от позиции.', '<li><span dir="rtl" lang="ar">جِئْتُ مِنْ قَبْلُ</span> — я пришёл прежде.</li><li><span dir="rtl" lang="ar">سَأَسَافِرُ مِنْ بَعْدُ</span> — я поеду позже.</li><li><span dir="rtl" lang="ar">جِئْتُ قَبْلَ الدَّرْسِ</span> — я пришёл до урока.</li>', '<span dir="rtl" lang="ar">قَبْلَ: ظَرْفُ زَمَانٍ مَنْصُوبٌ وَهُوَ مُضَافٌ.</span>'),
  ('13', 25, 'لَامُ الْأَمْرِ وَالْجَزْمُ بِالطَّلَبِ (Лям приказа и джазм через побуждение)', 'Лям приказа требует формы настоящего времени в джазме.', 'После لَامُ الْأَمْرِ глагол настоящего времени стоит в джазме. Джазм может также возникать как ответ на просьбу, приказ или запрет, если между частями имеется причинно-следственная связь.', '<li><span dir="rtl" lang="ar">لِيَكْتُبْ الطَّالِبُ</span> — пусть студент пишет.</li><li><span dir="rtl" lang="ar">اِجْتَهِدْ تَنْجَحْ</span> — старайся, и ты добьёшься успеха.</li><li><span dir="rtl" lang="ar">لَا تُهْمِلْ دَرْسَكَ</span> — не пренебрегай уроком.</li>', '<span dir="rtl" lang="ar">يَكْتُبْ: مُضَارِعٌ مَجْزُومٌ بِلَامِ الْأَمْرِ.</span>'),
  ('13', 26, 'النُّدْبَةُ وَأَدَوَاتُ الْجَزْمِ (Восклицательное обращение и частицы джазма)', 'Особые частицы вводят обращение или управляют формой глагола.', 'Нудба выражает эмоциональное обращение, часто с وَا. Частицы джазма, которые управляют одним глаголом, требуют сукуна или соответствующего окончания джазма у настоящего времени.', '<li><span dir="rtl" lang="ar">وَا مُحَمَّدَاهُ</span> — о, Мухаммад!</li><li><span dir="rtl" lang="ar">لَمْ يَذْهَبْ</span> — он не пошёл.</li><li><span dir="rtl" lang="ar">لَا تَكْذِبْ</span> — не лги.</li>', '<span dir="rtl" lang="ar">يَذْهَبْ: مُضَارِعٌ مَجْزُومٌ بِلَمْ وَعَلَامَةُ جَزْمِهِ السُّكُونُ.</span>'),
  ('14', 27, 'أَدَوَاتُ الشَّرْطِ غَيْرُ الْجَازِمَةِ (Неджазмовые условные частицы)', 'Частица إِذَا связывает условие с ожидаемым следствием, не ставя глагол в джазм.', 'إِذَا используется для реального или ожидаемого условия. В отличие от частиц джазма, она не изменяет окончание глагола настоящего времени.', '<li><span dir="rtl" lang="ar">إِذَا جَاءَ الْمُدَرِّسُ قُمْنَا</span> — когда преподаватель придёт, мы встанем.</li><li><span dir="rtl" lang="ar">إِذَا تَدْرُسُ تَفْهَمُ</span> — когда учишься, понимаешь.</li><li><span dir="rtl" lang="ar">إِذَا سَافَرْتَ فَأَخْبِرْنِي</span> — когда поедешь, сообщи мне.</li>', '<span dir="rtl" lang="ar">جَاءَ: فِعْلٌ مَاضٍ مَبْنِيٌّ فِي مَحَلِّ جَزْمٍ فِعْلُ الشَّرْطِ.</span>'),
  ('14', 28, 'اقْتِرَانُ جَوَابِ الشَّرْطِ بِالْفَاءِ (Фа перед ответом условия)', 'В некоторых типах ответа условию необходима частица فَ.', 'Фа связывает ответ с условием, когда ответ не может быть простым глаголом в джазме: например, это именное предложение, приказ, запрет или ответ с частицей.', '<li><span dir="rtl" lang="ar">إِنْ تَجْتَهِدْ فَأَنْتَ نَاجِحٌ</span> — если будешь стараться, ты успешен.</li><li><span dir="rtl" lang="ar">إِنْ تَحْضُرْ فَاجْلِسْ</span> — если придёшь, садись.</li><li><span dir="rtl" lang="ar">إِنْ تَسْأَلْ فَلَا تَخَفْ</span> — если спросишь, не бойся.</li>', '<span dir="rtl" lang="ar">فَأَنْتَ نَاجِحٌ: جَوَابُ الشَّرْطِ مُقْتَرِنٌ بِالْفَاءِ.</span>'),
  ('15', 29, 'أَدَوَاتُ الشَّرْطِ الْجَازِمَةُ (Джазмовые условные частицы)', 'Частицы условия ставят в джазм глагол условия и его ответ.', 'Частицы إِنْ, مَنْ, مَا и другие создают условную конструкцию. При наличии двух настоящих глаголов оба обычно находятся в джазме, если не возникает особая причина для другой формы.', '<li><span dir="rtl" lang="ar">إِنْ تَدْرُسْ تَنْجَحْ</span> — если будешь учиться, добьёшься успеха.</li><li><span dir="rtl" lang="ar">مَنْ يَجْتَهِدْ يَنْجَحْ</span> — кто старается, достигает успеха.</li><li><span dir="rtl" lang="ar">مَا تَفْعَلْ أَفْعَلْ</span> — что сделаешь ты, сделаю и я.</li>', '<span dir="rtl" lang="ar">تَدْرُسْ: مُضَارِعٌ مَجْزُومٌ فِعْلُ الشَّرْطِ.</span>'),
  ('15', 30, 'كَمِ الْخَبَرِيَّةُ وَحَتَّى (Сообщительное «сколько» и «даже/до тех пор»)', 'Эти частицы выражают множество или предел действия.', 'كَمِ الْخَبَرِيَّةُ сообщает о большом количестве и не требует вопросительного ответа. حَتَّى имеет несколько значений; в контексте она часто указывает на конечный предел действия.', '<li><span dir="rtl" lang="ar">كَمْ مِنْ كِتَابٍ قَرَأْتُ</span> — сколько же книг я прочитал.</li><li><span dir="rtl" lang="ar">سِرْتُ حَتَّى الْمَسْجِدِ</span> — я шёл до мечети.</li><li><span dir="rtl" lang="ar">دَرَسْتُ حَتَّى فَهِمْتُ</span> — я учился, пока не понял.</li>', '<span dir="rtl" lang="ar">كِتَابٍ: تَمْيِيزٌ مَجْرُورٌ بِمِنْ الزَّائِدَةِ.</span>'),
  ('16', 31, 'الْمُجَرَّدُ وَالْمَزِيدُ (Простой и расширенный глагол)', 'Глагол различается по наличию добавочных букв сверх корня.', 'Простой глагол состоит только из корневых букв, а расширенный содержит одну или несколько добавочных букв. Модель формы помогает понимать базовое направление значения, но конкретный перевод определяется словарём.', '<li><span dir="rtl" lang="ar">كَتَبَ</span> — написал.</li><li><span dir="rtl" lang="ar">أَكْتَبَ</span> — заставил написать.</li><li><span dir="rtl" lang="ar">اسْتَكْتَبَ</span> — попросил написать.</li>', '<span dir="rtl" lang="ar">اسْتَكْتَبَ: فِعْلٌ مَاضٍ مَزِيدٌ بِثَلَاثَةِ أَحْرُفٍ.</span>'),
  ('16', 32, 'أَوْزَانُ الْفِعْلِ وَجَمْعُ التَّكْسِيرِ (Модели глагола и ломаное множественное)', 'Модель показывает строение слова; ломаное множественное меняет внутренний рисунок.', 'Вес позволяет соотнести конкретное слово с формулой. Ломаное множественное не образуется простым присоединением окончания, поэтому его форма должна изучаться как словарная.', '<li><span dir="rtl" lang="ar">فَعَلَ يَفْعُلُ</span> — модель простого глагола.</li><li><span dir="rtl" lang="ar">كِتَابٌ كُتُبٌ</span> — книга, книги.</li><li><span dir="rtl" lang="ar">رَجُلٌ رِجَالٌ</span> — мужчина, мужчины.</li>', '<span dir="rtl" lang="ar">كُتُبٌ: جَمْعُ تَكْسِيرٍ مَرْفُوعٌ بِالضَّمَّةِ.</span>'),
  ('17', 33, 'بَابُ أَفْعَلَ (IV порода)', 'Четвёртая порода строится с хамзой в начале и часто передаёт побуждение к действию.', 'Форма أَفْعَلَ относится к расширенным формам глагола. Во многих случаях она делает значение переходным или каузативным, однако точный перевод каждой единицы следует брать из словаря.', '<li><span dir="rtl" lang="ar">أَخْرَجَ الطَّالِبُ الْكِتَابَ</span> — студент вынес книгу.</li><li><span dir="rtl" lang="ar">أَسْلَمَ الرَّجُلُ</span> — мужчина принял ислам.</li><li><span dir="rtl" lang="ar">أَحْسَنَ إِلَى جَارِهِ</span> — он проявил добро к соседу.</li>', '<span dir="rtl" lang="ar">أَخْرَجَ: فِعْلٌ مَاضٍ عَلَى وَزْنِ أَفْعَلَ.</span>'),
  ('17', 34, 'الْفِعْلُ الْمُتَعَدِّي إِلَى مَفْعُولَيْنِ (Глагол с двумя объектами)', 'Некоторые глаголы требуют двух дополнений для полного смысла.', 'У ряда глаголов два объекта: первый обычно обозначает того, кому сообщается или что изменяется, второй — содержание сообщения либо результат. Оба объекта стоят в насбе.', '<li><span dir="rtl" lang="ar">أَعْطَيْتُ الطَّالِبَ كِتَابًا</span> — я дал студенту книгу.</li><li><span dir="rtl" lang="ar">عَلَّمْتُ الْوَلَدَ الْقُرْآنَ</span> — я обучил мальчика Корану.</li><li><span dir="rtl" lang="ar">ظَنَنْتُ الْجَوَّ جَمِيلًا</span> — я счёл погоду прекрасной.</li>', '<span dir="rtl" lang="ar">الطَّالِبَ: مَفْعُولٌ بِهِ أَوَّلٌ مَنْصُوبٌ، كِتَابًا: مَفْعُولٌ بِهِ ثَانٍ مَنْصُوبٌ.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select
  'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إِعْرَاب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from rule_data;

insert into public.words (course_name, lesson_number, word_ar, word_ru) values
('Мединский курс (Том 3)','1','إِعْرَابٌ','грамматическое изменение окончания'),('Мединский курс (Том 3)','1','بِنَاءٌ','неизменяемость формы'),('Мединский курс (Том 3)','1','مَرْفُوعٌ','именительный падеж'),('Мединский курс (Том 3)','1','مَنْصُوبٌ','винительный падеж'),('Мединский курс (Том 3)','1','مَجْرُورٌ','родительный падеж'),('Мединский курс (Том 3)','1','حَالٌ','обстоятельство состояния'),
